/**
 * Renderer
 * 
 * Handles all DOM updates and UI interactions for Grantha Index.
 * Consumes the buckets generated by chronology-engine.js.
 */

// Global state for expanded cards
let expandedCardId = null;
let expandedEras = new Set();
let erasInitialized = false;

function initializeUI() {
    populateProposers();
    updateUI();
}

function populateProposers() {
    const proposers = new Set();
    worksData.forEach(w => {
        if (w.dates) {
            w.dates.forEach(d => {
                if (d.type !== 'scholarly_consensus' && d.proposer) proposers.add(d.proposer);
            });
        }
    });
    
    const filterEl = document.getElementById('proposer-filter');
    if (!filterEl) return;
    
    let html = '<option value="All">All Indic Proposers</option>';
    Array.from(proposers).sort().forEach(p => {
        html += `<option value="${p}">${p}'s Timeline</option>`;
    });
    filterEl.innerHTML = html;
}

function updateUI() {
    // 1. Get raw buckets from the engine
    let buckets = prepareTimelineData(worksData, currentViewMode, activeProposer);
    
    // 2. Render
    renderStats(buckets);
    renderEraSections(buckets);
}

function formatYear(y) {
    if (y < 0) return Math.abs(y) + ' BCE';
    return y + ' CE';
}

// applyFilters removed as we no longer have a search bar

function renderStats(buckets) {
    const totalWorks = buckets.reduce((sum, b) => sum + b.works.length, 0);
    
    const uniqueGenres = new Set();
    buckets.forEach(b => b.works.forEach(w => uniqueGenres.add(w.genre)));
    
    const container = document.getElementById('stats-ribbon');
    if(container) {
        container.innerHTML = `Showing ${totalWorks} works across ${uniqueGenres.size} genres`;
    }
}

// Genre filters removed.

function renderEraSections(buckets) {
    const container = document.getElementById('catalog-grid');
    if (!container) return;
    
    let html = '';
    
    if (!erasInitialized && buckets.length > 0) {
        expandedEras.add(buckets[0].label);
        erasInitialized = true;
    }
    
    buckets.forEach(b => {
        if (b.works.length === 0) return;
        
        // Calculate genre insights for the bucket
        const genreCounts = {};
        b.works.forEach(w => {
            genreCounts[w.genre] = (genreCounts[w.genre] || 0) + 1;
        });
        
        const insightArr = Object.entries(genreCounts).map(([genreId, count]) => {
            const tax = taxonomyMap[genreId];
            const title = tax ? tax.title_en : genreId;
            return `${count} ${title}${count > 1 && title !== 'Itihasa' && !title.endsWith('s') ? 's' : ''}`;
        });
        const insightText = insightArr.join(' • ');
        
        const isExpanded = expandedEras.has(b.label);
        const safeLabel = b.label.replace(/'/g, "\\'");
        
        html += `
            <section class="era-section">
                <div class="era-marker"></div>
                <div class="era-header-clickable" onclick="toggleEra('${safeLabel}')">
                    <h2 class="era-title">
                        ${b.label}
                        <span class="era-chevron">${isExpanded ? '▼' : '▶'}</span>
                    </h2>
                    <div class="era-insight">${b.works.length} works total — ${insightText}</div>
                </div>
                ${isExpanded ? `
                <div class="card-grid">
                    ${b.works.map(w => renderWorkCard(w)).join('')}
                </div>
                ` : ''}
            </section>
        `;
    });
    
    if (html === '') {
        html = `<div style="padding: 4rem; text-align: center; color: var(--text-muted);">No works match your filters.</div>`;
    }
    
    container.innerHTML = html;
    container.style.display = 'block';
    
    const controlsBar = document.getElementById('controls-bar');
    if (controlsBar) controlsBar.style.display = 'flex';
    
    document.getElementById('loading').style.display = 'none';
}

function toggleEra(label) {
    if (expandedEras.has(label)) {
        expandedEras.delete(label);
    } else {
        expandedEras.add(label);
    }
    updateUI(); // Re-render to show/hide expanded state
}

function toggleCard(id) {
    expandedCardId = expandedCardId === id ? null : id;
    updateUI(); // Re-render to show/hide expanded state
}

function getGenreClass(genreId) {
    const map = {
        'veda-samhita': 'genre-veda-samhita',
        'upanishad': 'genre-upanishad',
        'itihasa': 'genre-itihasa',
        'gita': 'genre-gita',
        'mahapurana': 'genre-mahapurana',
        'darshana': 'genre-darshana',
        'dharmashastra': 'genre-dharmashastra',
        'science': 'genre-science',
        'arts': 'genre-arts',
        'sangam': 'genre-sangam',
        'bhakti': 'genre-bhakti'
    };
    return map[genreId] || 'genre-default';
}

function calculateBarPercentage(start, end) {
    // Project -2000 to 2000 onto 0-100%
    const min = -2000;
    const max = 2000;
    const range = max - min;
    
    // Clamp values
    const s = Math.max(min, Math.min(max, start));
    const e = Math.max(min, Math.min(max, end));
    
    let left = ((s - min) / range) * 100;
    let width = ((e - s) / range) * 100;
    
    // Ensure minimum width so it's visible
    if (width < 2) width = 2;
    // Don't overflow right edge
    if (left + width > 100) left = 100 - width;
    
    return { left, width };
}

function renderDigitalReadiness(score) {
    let html = '<div class="digital-readiness" title="Digital Readiness Score">';
    for (let i = 1; i <= 4; i++) {
        html += `<div class="dot ${i <= score ? 'active' : ''}"></div>`;
    }
    html += '</div>';
    return html;
}

function getReadinessScore(w) {
    if (!w.digital) return 0;
    // Simple heuristic for now
    let score = 1;
    if (w.digital.dharmicdata) score += 1;
    if (w.digital.iitk_reader) score += 2;
    return Math.min(4, score);
}

function renderWorkCard(w) {
    const isExpanded = w.id === expandedCardId;
    const activeDateObj = getActiveDate(w, currentViewMode, activeProposer);
    
    const startYear = activeDateObj ? activeDateObj.start_year : 0;
    const endYear = activeDateObj ? activeDateObj.end_year : 0;
    
    const datesStr = activeDateObj ? 
        (startYear === endYear ? formatYear(startYear) : `${formatYear(startYear)} – ${formatYear(endYear)}`) 
        : 'Unknown Date';
        
    const isImputed = activeDateObj && activeDateObj.isImputed;
    
    const tax = taxonomyMap[w.genre] || { title_en: w.genre };
    const genreClass = getGenreClass(w.genre);
    
    const barStyle = calculateBarPercentage(startYear, endYear);
    
    let altDatesHtml = '';
    if (w.dates && w.dates.length > 1) {
        const alts = w.dates.filter(d => d.type !== 'scholarly_consensus');
        if (alts.length > 0) {
            altDatesHtml = alts.map(alt => `
                <div class="alt-date-row">
                    <span>${alt.proposer}</span>
                    <span>${formatYear(alt.start_year)}</span>
                </div>
            `).join('');
        }
    }

    return `
        <article class="work-card ${isExpanded ? 'expanded' : ''}" onclick="toggleCard('${w.id}')">
            <div class="card-main">
                <div class="work-meta-header">
                    <div class="genre-badge-wrapper">
                        <span class="genre-badge ${genreClass}">${tax.title_en}</span>
                        <div class="genre-tooltip">
                            <div class="tooltip-title">${tax.title_en}</div>
                            ${tax.etymology ? `<div class="tooltip-ety">${tax.etymology}</div>` : ''}
                            <div>${tax.meaning || 'No definition available.'}</div>
                        </div>
                    </div>
                </div>
                
                <h3 class="book-title-en">${w.title_en}</h3>
                <div class="book-title-sa">${w.title_sa || ''}</div>
                
                <div class="date-text">${datesStr} ${isImputed ? '(Imputed)' : ''}</div>
                <div class="date-bar-container">
                    <div class="date-bar-fill ${isImputed ? 'imputed' : ''}" 
                         style="left: ${barStyle.left}%; width: ${barStyle.width}%;"></div>
                </div>
                
                <p class="work-summary">${w.summary || 'No summary available.'}</p>
                
                ${w.etymology && !isExpanded ? `<div class="work-etymology">${w.etymology}</div>` : ''}
                
                ${renderDigitalReadiness(getReadinessScore(w))}
            </div>
            
            ${isExpanded ? `
            <div class="expanded-details">
                ${w.etymology ? `
                    <div class="detail-section">
                        <div class="detail-label">Etymology</div>
                        <div class="detail-value" style="font-style:italic; color: var(--accent-clay);">${w.etymology}</div>
                    </div>
                ` : ''}
                
                <div class="detail-section">
                    <div class="detail-label">Genre Definition</div>
                    <div class="detail-value">${tax.meaning || 'No definition.'}</div>
                </div>
                
                ${w.structure ? `
                    <div class="detail-section">
                        <div class="detail-label">Structure</div>
                        <div class="detail-value">${w.structure}</div>
                    </div>
                ` : ''}
                
                ${altDatesHtml ? `
                    <div class="detail-section">
                        <div class="detail-label">Indic Datings</div>
                        ${altDatesHtml}
                    </div>
                ` : ''}
            </div>
            ` : ''}
        </article>
    `;
}
